if (aAdminUsers.length > 0) {
  db.admin_users.insertMany(aAdminUsers);
}
if (aGameTypes.length > 0) {
  db.game_types.insertMany(aGameTypes);
}
if (aGames.length > 0) {
  db.games.insertMany(aGames);
}
if (aTables.length > 0) {
  db.tables.insertMany(aTables);
}

// tx-table_records、tx-table_record_logs 在 MySQL dump 裡沒有資料，
// 這裡只建立 collection 跟索引，不塞資料。
db.createCollection("table_records");
db.createCollection("table_record_logs");

// ------------------------------------------------------------
// 索引（對應 MySQL dump 裡的 UNIQUE KEY / KEY）
// ------------------------------------------------------------

db.admin_users.createIndex({ name: 1 }, { unique: true, name: "admin_users-name" });
db.admin_users.createIndex({ deleted_at: 1 }, { name: "admin_users-da" });

db.game_types.createIndex({ key: 1 }, { unique: true, name: "game_types-k" });
db.game_types.createIndex({ name: 1, deleted_at: 1 }, { name: "game_types-n-da" });
db.game_types.createIndex({ deleted_at: 1 }, { name: "game_types-da" });

db.games.createIndex({ key: 1 }, { unique: true, name: "games-k" });
db.games.createIndex({ name: 1, deleted_at: 1 }, { name: "games-n-da" });
db.games.createIndex({ deleted_at: 1 }, { name: "games-da" });
db.games.createIndex({ game_type_id: 1, deleted_at: 1 }, { name: "games-gti-da" });

db.tables.createIndex({ key: 1 }, { unique: true, name: "tables-key" });
db.tables.createIndex({ deleted_at: 1 }, { name: "tables-da" });
db.tables.createIndex({ no: 1, deleted_at: 1 }, { name: "tables-n-da" });

db.table_records.createIndex({ no: 1 }, { unique: true, name: "table_records-n" });
db.table_records.createIndex(
  { table_id: 1, game_id: 1, no: 1, deleted_at: 1 },
  { name: "table_records-ti-gi-n-da" }
);

db.table_record_logs.createIndex(
  { table_record_id: 1, game_id: 1, state: 1 },
  { name: "table_record_logs-tri-gi-s" }
);

// ------------------------------------------------------------
// counters（自增序號，供 AbstractMongodb.nextId() 使用）
// ------------------------------------------------------------

db.counters.deleteMany({
  _id: { $in: ["admin_user", "game_type", "game", "table", "table_record", "table_record_log"] },
});
db.counters.insertMany([
  { _id: "admin_user", seq: aAdminUsers.length },
  { _id: "game_type", seq: aGameTypes.length },
  { _id: "game", seq: aGames.length },
  { _id: "table", seq: aTables.length },
  { _id: "table_record", seq: 0 },
  { _id: "table_record_log", seq: 0 },
]);
